 function installAdvisorWorkbench(){
  const nav=$('ftAIStageNav');if(!nav||nav.dataset.bound)return;nav.dataset.bound='1';nav.addEventListener('click',e=>{const b=e.target.closest('button[data-stage]');if(b)renderAdvisorStage(b.dataset.stage)});renderAdvisorStage('foundation');
 }
 // v8 open/close lifecycle: make the advisor a true isolated page, not a translucent popup over finance screens.
 const appSiblings=[];
 function isolateApp(isolate){
  if(isolate){document.body.classList.add('ftai-advisor-open');Array.from(document.body.children).forEach(el=>{if(el!==panel&&el!==launcher){appSiblings.push({el,inert:!!el.inert,aria:el.getAttribute('aria-hidden')});el.inert=true;el.setAttribute('aria-hidden','true')}})}
  else{document.body.classList.remove('ftai-advisor-open');while(appSiblings.length){const x=appSiblings.pop();if(!x.el.isConnected)continue;x.el.inert=x.inert;if(x.aria===null)x.el.removeAttribute('aria-hidden');else x.el.setAttribute('aria-hidden',x.aria)}}
 }

